import heapq

def match(orders):
    book = {}  # id -> dict(side, price, qty, seq)
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0
    trades = []

    def add_resting(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def top_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            if oid in book and book[oid]['qty'] > 0:
                return item
            heapq.heappop(heap)
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty
        seq_counter += 1
        seq = seq_counter

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            top = top_valid(opp_heap)
            if top is None:
                break

            if side == 'buy':
                resting_price = top[0]
            else:
                resting_price = -top[0]

            if typ != 'market':
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            opp_id = top[2]
            opp_order = book[opp_id]
            trade_qty = min(remaining, opp_order['qty'])
            trade_price = opp_order['price']

            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            opp_order['qty'] -= trade_qty

            if opp_order['qty'] == 0:
                del book[opp_id]
                heapq.heappop(opp_heap)
            # else: partially filled, stays at top for next iteration

        if typ == 'limit' and remaining > 0:
            add_resting(oid, side, price, remaining, seq)
        # ioc/market: remainder discarded

    return trades

